test "auth product all flow shards" {
    const gpa = std.testing.allocator;
    const list = try listProviders(gpa);
    defer gpa.free(list);
    try std.testing.expect(list.len > 100);
    const hdrs = try formatAllBearerHeaders(gpa, "tok");
    defer gpa.free(hdrs);
    try std.testing.expect(std.mem.indexOf(u8, hdrs, "Bearer tok") != null);
}
